'use strict';
const $=id=>document.getElementById(id);
const euro=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
const round=n=>Math.round((n+Number.EPSILON)*100)/100;
const seeds=BottegaEngine.demoCatalog();
let state=window.bottegaInitialState||{catalog:seeds,quotes:[],draft:null};
let saveTimer,saveQueue=Promise.resolve(),pending=false,saveRevision=0;
function enqueueSave(){clearTimeout(saveTimer);const snapshot=JSON.stringify(state),revision=saveRevision;saveQueue=saveQueue.catch(()=>{}).then(()=>window.bottegaApi('/api/state',{method:'PUT',body:snapshot})).then(()=>{if(revision===saveRevision){pending=false;$('save-hint').textContent='Modifiche salvate in questo browser.'}});return saveQueue}
window.bottegaFlush=()=>pending?enqueueSave():saveQueue;
window.addEventListener('beforeunload',e=>{if(pending){e.preventDefault();e.returnValue=''}});
function blank(){const d=new Date();return{id:null,business:'',customer:'',job:'',number:`PREV-${d.getFullYear()}-${String(state.quotes.length+1).padStart(3,'0')}`,date:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,labor:0,laborMode:'hourly',hours:0,hourlyRate:state.settings?.hourlyRate??100,vat:22,notes:'',lines:[]}}
let draft=state.draft||blank();
function validQuote(q){return q&&['business','customer','job','number','date','notes'].every(k=>typeof q[k]==='string')&&/^\d{4}-\d{2}-\d{2}$/.test(q.date)&&[0,4,10,22].includes(q.vat)&&Number.isFinite(q.labor)&&q.labor>=0&&q.labor<=10000&&(q.id===null||typeof q.id==='string')&&Array.isArray(q.lines)&&q.lines.length<=1000&&q.lines.every(l=>typeof l.id==='string'&&typeof l.name==='string'&&typeof l.unit==='string'&&Number.isFinite(l.qty)&&l.qty>=0&&l.qty<=1e8&&Number.isFinite(l.price)&&l.price>=0&&l.price<=1e8)}
function validState(s){return s&&Array.isArray(s.catalog)&&s.catalog.length<=10000&&s.catalog.every(c=>typeof c.id==='string'&&typeof c.name==='string'&&typeof c.unit==='string'&&Number.isFinite(c.price)&&c.price>=0&&c.price<=1e8)&&Array.isArray(s.quotes)&&s.quotes.length<=10000&&s.quotes.every(q=>validQuote(q)&&typeof q.id==='string')&&(!s.draft||validQuote(s.draft))}
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4200)}
function persist(){state.draft=draft;pending=true;saveRevision++;clearTimeout(saveTimer);$('save-hint').textContent='Salvataggio in corso…';saveTimer=setTimeout(()=>enqueueSave().catch(e=>{$('save-hint').textContent='Non salvato: '+e.message;toast('Salvataggio non riuscito. Riprova o esporta un backup.')}),450);return true}
function totals(q=draft){return BottegaEngine.totals(q)}
function update(){const t=totals();for(const [id,n] of Object.entries({'materials-total':t.materials,'labor-total':t.labor,'sum-materials':t.materials,'sum-labor':t.labor,'sum-net':t.net,'sum-vat':t.vat,'sum-total':t.total}))$(id).textContent=euro(n);$('sum-rate').textContent=`${draft.hours} h × ${euro(draft.hourlyRate)}`;$('line-count').textContent=`${draft.lines.length} ${draft.lines.length===1?'voce':'voci'}`;$('saved-count').textContent=state.quotes.length;$('empty-lines').hidden=draft.lines.length>0;$('document-label').textContent=draft.id?'IN MODIFICA':'BOZZA';persist()}
function loadEditor(){if(draft.laborMode!=='hourly'){const old=totals(draft).labor;draft.hourlyRate=state.settings?.hourlyRate||100;draft.hours=Number((old/draft.hourlyRate).toFixed(8));draft.laborMode='hourly';}for(const id of ['business','customer','job','number','date','hours','hourlyRate','vat','notes'])$(id).value=draft[id];renderLines();update()}
function renderLines(){$('lines').innerHTML=draft.lines.map(l=>`<tr data-id="${esc(l.id)}"><td><input data-field="name" aria-label="Descrizione materiale" value="${esc(l.name)}"><div class="unit">${esc(l.unit)}</div></td><td><input data-field="qty" type="number" min="0" max="100000000" step="0.01" aria-label="Quantità" value="${l.qty}"></td><td><input data-field="price" type="number" min="0" max="100000000" step="0.01" aria-label="Prezzo unitario" value="${l.price}"></td><td class="line-total">${euro(round(l.qty*l.price))}</td><td><button class="remove" aria-label="Rimuovi materiale">×</button></td></tr>`).join('')}
function renderPicker(){$('material-select').innerHTML='<option value="">Cerca un materiale nel tuo listino…</option>'+state.catalog.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${euro(c.price)}/${esc(c.unit)}</option>`).join('')}
function show(view){document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==view);document.querySelectorAll('nav button').forEach(el=>el.classList.toggle('active',el.dataset.view===view));if(view==='archive')renderArchive();if(view==='catalog')renderCatalog()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>show(b.dataset.view));
for(const id of ['business','customer','job','number','date','notes'])$(id).addEventListener('input',()=>{draft[id]=$(id).value;persist()});
for(const id of ['hours','hourlyRate'])$(id).addEventListener('input',()=>{draft[id]=Math.min(100000,Math.max(0,Number($(id).value)||0));draft.laborMode='hourly';update()});
$('vat').onchange=()=>{draft.vat=Number($('vat').value);update()};
$('lines').addEventListener('input',e=>{const field=e.target.dataset.field;if(!field)return;const l=draft.lines.find(x=>x.id===e.target.closest('tr').dataset.id);l[field]=field==='name'?e.target.value:Math.min(1e8,Math.max(0,Number(e.target.value)||0));e.target.closest('tr').querySelector('.line-total').textContent=euro(round(l.qty*l.price));update()});
$('lines').addEventListener('click',e=>{if(!e.target.closest('.remove'))return;draft.lines=draft.lines.filter(l=>l.id!==e.target.closest('tr').dataset.id);renderLines();update()});
$('add-material').onclick=()=>{const c=state.catalog.find(c=>c.id===$('material-select').value);if(!c){toast('Scegli prima un materiale dal listino.');return}draft.lines.push({...c,id:uid(),qty:1});renderLines();update()};
$('add-line').onclick=()=>{draft.lines.push({id:uid(),name:'',unit:'pz',price:0,qty:1});renderLines();update();$('lines').lastElementChild.querySelector('input').focus()};
$('new').onclick=()=>{if((draft.lines.length||draft.job||draft.customer)&&!confirm('Creare un nuovo preventivo? Le modifiche alla bozza non salvate nell’archivio verranno sostituite.'))return;const business=draft.business;draft=blank();draft.business=business;loadEditor()};
function ready(){if(draft.lines.some(l=>l.missing)){toast('Completa e verifica i componenti mancanti prima di salvare o stampare.');return false}if(!draft.customer.trim()||!draft.job.trim()||!draft.number.trim()||!draft.date){toast('Inserisci cliente, titolo, numero e data del preventivo.');return false}if(!draft.lines.length||draft.lines.some(l=>!l.name.trim()||l.qty<=0)){toast('Aggiungi materiali con descrizione e quantità maggiore di zero.');return false}return true}
$('save').onclick=async()=>{if(!ready())return;const id=draft.id||uid();draft.id=id;const copy=JSON.parse(JSON.stringify(draft));const index=state.quotes.findIndex(q=>q.id===id);if(index<0)state.quotes.push(copy);else state.quotes[index]=copy;update();try{await window.bottegaFlush();toast('Preventivo salvato in questo browser.')}catch(e){toast('Salvataggio non riuscito: '+e.message)}};
function renderArchive(){$('archive-list').innerHTML=state.quotes.length?state.quotes.slice().reverse().map(q=>`<article class="card archive-item"><div><div class="eyebrow">${esc(q.number)} · ${esc(q.date.split('-').reverse().join('/'))}</div><h2>${esc(q.job)}</h2><p>${esc(q.customer)}</p></div><div class="archive-actions"><strong>${euro(totals(q).total)}</strong><button class="secondary" data-action="open" data-id="${esc(q.id)}">Apri</button><button class="secondary" data-action="copy" data-id="${esc(q.id)}">Duplica</button><button class="secondary" data-action="delete" data-id="${esc(q.id)}" aria-label="Elimina preventivo">×</button></div></article>`).join(''):'<div class="card empty-inline">Ancora nessun preventivo salvato.<br><span>Il prossimo lavoro sarà il primo del tuo archivio.</span></div>'}
$('archive-list').onclick=e=>{const b=e.target.closest('button[data-action]');if(!b)return;const q=state.quotes.find(q=>q.id===b.dataset.id);if(b.dataset.action==='delete'){if(!confirm(`Eliminare ${q.number} dall’archivio?`))return;state.quotes=state.quotes.filter(x=>x.id!==q.id);if(draft.id===q.id)draft.id=null;persist();renderArchive();update();return}if((draft.lines.length||draft.job||draft.customer)&&!confirm('Aprire questo preventivo? Le modifiche alla bozza non salvate nell’archivio verranno sostituite.'))return;draft=JSON.parse(JSON.stringify(q));if(b.dataset.action==='copy'){draft.id=null;draft.number=blank().number}loadEditor();show('editor');window.scrollTo(0,0)};
function renderCatalog(){$('catalog-list').innerHTML=state.catalog.map(c=>`<div class="catalog-row" data-id="${esc(c.id)}"><span>${esc(c.name)} <small class="muted">/ ${esc(c.unit)}</small></span><input type="number" min="0" max="100000000" step="0.01" aria-label="Prezzo ${esc(c.name)}" value="${c.price}"><span class="muted" style="flex:0">€</span><button aria-label="Elimina ${esc(c.name)}">Rimuovi</button></div>`).join('')||'<p>Il listino è vuoto. Aggiungi il primo materiale.</p>'}
$('catalog-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.get('name').trim()||!f.get('unit').trim())return;state.catalog.push({id:uid(),name:f.get('name').trim(),unit:f.get('unit').trim(),price:round(Number(f.get('price')))});persist();renderCatalog();renderPicker();e.target.reset();toast('Materiale aggiunto al listino.')};
$('catalog-list').onchange=e=>{if(e.target.tagName!=='INPUT')return;const c=state.catalog.find(c=>c.id===e.target.closest('.catalog-row').dataset.id);c.price=round(Math.min(1e8,Math.max(0,Number(e.target.value)||0)));e.target.value=c.price;persist();renderPicker()};
$('catalog-list').onclick=e=>{if(e.target.tagName!=='BUTTON')return;const id=e.target.closest('.catalog-row').dataset.id;if(!confirm('Rimuovere il materiale dal listino? I preventivi già compilati manterranno questa voce.'))return;state.catalog=state.catalog.filter(c=>c.id!==id);persist();renderCatalog();renderPicker()};
$('export').onclick=()=>{state.draft=draft;const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`bottega-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1800000)throw Error();const next=JSON.parse(await file.text());if(!validState(next))throw Error();if(!confirm('Sostituire tutti i dati di questo browser con questo backup? Esporta prima i dati attuali se vuoi conservarli.'))return;await window.bottegaFlush();await window.bottegaApi('/api/state',{method:'PUT',body:JSON.stringify(next)});state=next;window.dispatchEvent(new Event('bottega-state-loaded'));draft=state.draft||blank();renderPicker();loadEditor();renderArchive();toast('Backup importato in questo browser.')}catch{toast('Importazione non riuscita. Verifica il file e la connessione.')}finally{e.target.value=''}};
$('print').onclick=()=>{if(!ready())return;const t=totals();$('print-document').innerHTML=`<div class="print-meta"><h2>${esc(draft.business||'Preventivo lavori')}</h2><p>${esc(draft.number)}<br>${esc(draft.date.split('-').reverse().join('/'))}</p></div><h1>${esc(draft.job)}</h1><p>Spett.le ${esc(draft.customer)}</p><table><thead><tr><th>Descrizione</th><th>Quantità</th><th>Prezzo unitario</th><th>Totale</th></tr></thead><tbody>${draft.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${l.qty} ${esc(l.unit)}</td><td>${euro(l.price)}</td><td>${euro(round(l.qty*l.price))}</td></tr>`).join('')}</tbody></table><div class="print-totals"><div><span>Materiali</span><b>${euro(t.materials)}</b></div><div><span>Manodopera (${draft.hours} h × ${euro(draft.hourlyRate)})</span><b>${euro(t.labor)}</b></div><div><span>Imponibile</span><b>${euro(t.net)}</b></div><div><span>IVA (${draft.vat}%)</span><b>${euro(t.vat)}</b></div><div class="print-final"><span>Totale</span><b>${euro(t.total)}</b></div></div>${draft.notes?`<h2>Note e condizioni</h2><p>${esc(draft.notes)}</p>`:''}`;window.print()};
renderPicker();loadEditor();


